    'PEN': { symbol: 'S/', position: 'prefix' },
    'GTQ': { symbol: 'Q', position: 'prefix' },
    'CRC': { symbol: '₡', position: 'prefix' },
    'UYU': { symbol: '$U', position: 'prefix' },
    'PYG': { symbol: '₲', position: 'prefix', decimals: 0 },
    'BOB': { symbol: 'Bs.', position: 'prefix' },
    'DOP': { symbol: 'RD$', position: 'prefix' },
    'HNL': { symbol: 'L', position: 'prefix' },
    'NIO': { symbol: 'C$', position: 'prefix' },
    'PAB': { symbol: 'B/.', position: 'prefix' },
    'JMD': { symbol: 'J$', position: 'prefix' },
    'TTD': { symbol: 'TT$', position: 'prefix' },
    // Europe
    'EUR': { symbol: '€', position: 'prefix' },
    'GBP': { symbol: '£', position: 'prefix' },
    'CHF': { symbol: 'CHF', position: 'suffix' },
    'SEK': { symbol: 'kr', position: 'suffix' },
    'NOK': { symbol: 'kr', position: 'suffix' },
    'DKK': { symbol: 'kr', position: 'suffix' },
    'PLN': { symbol: 'zł', position: 'suffix' },
