    'ISK': { symbol: 'kr', position: 'suffix', decimals: 0 },
    'RUB': { symbol: '₽', position: 'prefix' },
    'BYN': { symbol: 'Br', position: 'suffix' },
    'TRY': { symbol: '₺', position: 'prefix' },
    // Asia-Pacific
    'JPY': { symbol: '¥', position: 'prefix', decimals: 0 },
