/**
 * Format currency amount according to user settings
 * @param {number} amount - Amount to format
 * @param {string|null} currency - Currency code (e.g., 'USD', 'EUR')
 * @param {object} settings - User settings object
 * @returns {string} Formatted currency string
 */
/**
 * Decimal places for a currency: the currency's native precision (crypto/JOD/etc.)
 * or the user's fiat default. Drives both display and input `step` (#331).
 * @param {string} currency - Currency code (e.g. 'BTC', 'USD')
 * @param {object} settings - User settings
 * @returns {number}
 */
export function currencyDecimals(currency, settings = {}) {
    const config = CURRENCY_CONFIG[currency];
    if (config && config.decimals !== undefined) {
        return config.decimals;
    }
    // Decimal Places = 0 is a display choice (formatCurrency honours it); an
    // amount field still takes pence, or 12.99 could not be entered at all.
    return parseInt(settings.number_format_decimals) || 2;
}

/**
 * The HTML number-input `step` for a currency (e.g. '0.00000001' for BTC,
 * '0.01' for USD, '1' for JPY).
 * @param {string} currency
 * @param {object} settings
 * @returns {string}
 */
export function currencyStep(currency, settings = {}) {
    const dp = currencyDecimals(currency, settings);
    return dp > 0 ? '0.' + '0'.repeat(dp - 1) + '1' : '1';
}

export function formatCurrency(amount, currency, settings) {
    const currencyCode = currency || getPrimaryCurrency([], settings);
    const config = CURRENCY_CONFIG[currencyCode] || { symbol: currencyCode, position: 'prefix' };
    // Use currency-native decimals for crypto, user setting for fiat. A
    // setting of 0 is a choice, not "unset": `parseInt(...) || 2` read it as 2.
    const chosen = parseInt(settings?.number_format_decimals, 10);
    const decimals = config.decimals !== undefined ? config.decimals : (Number.isNaN(chosen) ? 2 : chosen);
    const decimalSep = settings.number_format_decimal_sep || '.';
    const thousandsSep = settings.number_format_thousands_sep ?? ',';

    // Format the number manually using user settings
    const absAmount = Math.abs(amount);
    const parts = absAmount.toFixed(decimals).split('.');
    const intPart = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, thousandsSep);
    const decPart = parts[1] || '';

    const { symbol, position } = config;

    const formattedNumber = decimals > 0 ? `${intPart}${decimalSep}${decPart}` : intPart;
    const sign = amount < 0 ? '-' : '';

    // Apply symbol based on position (suffix currencies get a space before the symbol)
    if (position === 'suffix') {
        return `${sign}${formattedNumber} ${symbol}`;
    } else {
        return `${sign}${symbol}${formattedNumber}`;
    }
}

/**
 * Get primary currency based on account balances
 * @param {array} accounts - Array of account objects
 * @param {object} settings - User settings object
 * @returns {string} Primary currency code
 */
export function getPrimaryCurrency(accounts, settings) {
    return settings?.default_currency || 'GBP';
}

/**
 * Format date string according to user settings
 * @param {string} dateStr - Date string in YYYY-MM-DD format
 * @param {object} settings - User settings object
 * @returns {string} Formatted date string
 */
export function formatDate(dateStr, settings) {
    if (!dateStr) return '';

    // Parse date string directly to avoid timezone conversion issues
    // Assumes dateStr is in YYYY-MM-DD format from backend
    const parts = dateStr.split(/[-/]/);
    if (parts.length !== 3) {
        // Fallback for unexpected format
        return dateStr;
    }

    const year = parseInt(parts[0], 10);
    const month = parseInt(parts[1], 10);
    const day = parseInt(parts[2], 10);

    // Use user's date format preference from settings
    const format = settings?.date_format || 'Y-m-d';

    // Format the date according to PHP date format codes, in one pass: a
    // month name put in by one code must not be read by the next ("janv."
    // has a j in it).
    const pad = (num) => String(num).padStart(2, '0');
    const tokens = {
        Y: () => String(year),
        m: () => pad(month),
        d: () => pad(day),
        M: () => monthName(month, 'short'),
        j: () => String(day),
    };
    return format.replace(/[YmdMj]/g, token => tokens[token]());
}

/**
 * Format account type for display
 * @param {string} type - Account type code
 * @returns {string} Formatted account type name
 */
export function formatAccountType(type) {
    if (!type) return '';
    const typeNames = {
        checking: t('budget', 'Checking'),
        savings: t('budget', 'Savings'),
        credit_card: t('budget', 'Credit Card'),
        investment: t('budget', 'Investment'),
        cash: t('budget', 'Cash'),
        loan: t('budget', 'Loan'),
        mortgage: t('budget', 'Mortgage'),
        pension: t('budget', 'Pension'),
        cryptocurrency: t('budget', 'Cryptocurrency')
    };
    return typeNames[type] || type.replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
}

/**
 * Format currency in compact form (with K/M suffix)
 * @param {number} value - Amount to format
 * @param {string|null} currency - Currency code
 * @param {object} settings - User settings object
 * @returns {string} Compact formatted currency string
 */
export function formatCurrencyCompact(value, currency, settings) {
    settings = settings || {};
    const currencyCode = currency || getPrimaryCurrency([], settings);
    const config = CURRENCY_CONFIG[currencyCode] || { symbol: currencyCode, position: 'prefix' };
    const { symbol, position } = config;

    const decimalSep = settings.number_format_decimal_sep || '.';
    const thousandsSep = settings.number_format_thousands_sep ?? ',';

    let scaledValue, suffix;

    if (Math.abs(value) >= 1000000) {
        scaledValue = value / 1000000;
        suffix = 'M';
    } else if (Math.abs(value) >= 1000) {
        scaledValue = value / 1000;
        suffix = 'K';
    } else if (Number.isInteger(value)) {
        // A round figure (an axis tick) reads better without ".00".
        scaledValue = value;
        suffix = '';
    } else {
        // No scaling needed, use regular formatting
        return formatCurrency(value, currency, settings);
    }

    // Format the scaled number: one decimal at most, and none when it is .0
    // ("£4K", not "£4.0K").
    const absScaled = Math.abs(scaledValue);
    const formatted = absScaled.toFixed(suffix ? 1 : 0).replace(/\.0$/, '');
    const parts = formatted.split('.');
    const intPart = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, thousandsSep);
    const decPart = parts[1] || '';
    const formattedNumber = decPart ? `${intPart}${decimalSep}${decPart}` : intPart;
    const sign = scaledValue < 0 ? '-' : '';

    // Apply currency symbol and K/M suffix based on position
    if (position === 'suffix') {
        return `${sign}${formattedNumber}${suffix} ${symbol}`;
    } else {
        return `${sign}${symbol}${formattedNumber}${suffix}`;
    }
}


/**
 * Format a Date object as YYYY-MM-DD without timezone conversion.
 * This prevents off-by-one day errors when working with local dates.
 *
 * @param {Date} date - Date object to format
 * @returns {string} Date string in YYYY-MM-DD format
 */
export function formatDateForAPI(date) {
    const year = date.getFullYear();
    const month = String(date.getMonth() + 1).padStart(2, '0');
    const day = String(date.getDate()).padStart(2, '0');
    return `${year}-${month}-${day}`;
}

/**
 * Get today's date as YYYY-MM-DD string without timezone conversion.
 *
 * @returns {string} Today's date in YYYY-MM-DD format
 */
export function getTodayDateString() {
    return formatDateForAPI(new Date());
}

/**
 * Get the first day of a month as YYYY-MM-DD string.
 *
 * @param {number} year - Full year (e.g., 2026)
 * @param {number} month - Month number (1-12, NOT 0-11)
 * @returns {string} First day of month in YYYY-MM-DD format
 */
export function getMonthStart(year, month) {
    return `${year}-${String(month).padStart(2, '0')}-01`;
}

/**
 * Get the last day of a month as YYYY-MM-DD string.
 *
 * @param {number} year - Full year (e.g., 2026)
 * @param {number} month - Month number (1-12, NOT 0-11)
 * @returns {string} Last day of month in YYYY-MM-DD format
 */
export function getMonthEnd(year, month) {
    const lastDay = new Date(year, month, 0).getDate();
    return `${year}-${String(month).padStart(2, '0')}-${String(lastDay).padStart(2, '0')}`;
}

/**
 * Parse a YYYY-MM-DD date string as local midnight (not UTC).
 * Avoids timezone issues where new Date("YYYY-MM-DD") creates UTC midnight.
 *
 * @param {string} dateStr - Date string in YYYY-MM-DD format
 * @returns {Date} Date object at local midnight
 */
export function parseLocalDate(dateStr) {
    const [year, month, day] = dateStr.split('-').map(Number);
    return new Date(year, month - 1, day);
}

/**
 * Calculate the number of days between two YYYY-MM-DD date strings.
 * Positive result means dateStr2 is after dateStr1.
 *
 * @param {string} dateStr1 - First date (YYYY-MM-DD)
 * @param {string} dateStr2 - Second date (YYYY-MM-DD)
 * @returns {number} Number of days between dates
 */
export function daysBetweenDates(dateStr1, dateStr2) {
    const date1 = parseLocalDate(dateStr1);
    const date2 = parseLocalDate(dateStr2);
    return Math.round((date2 - date1) / (1000 * 60 * 60 * 24));
}

/**
 * Get date range for a budget period.
 *
 * @param {string} period - Period type: 'weekly', 'monthly', 'quarterly', 'yearly'
 * @param {number} [startDay=1] - Day of month when budget cycle starts (1-31, monthly only)
 * @returns {object} Object with {start, end, label} date strings
 */
export function getPeriodDateRange(period, startDay = 1, referenceDate = null) {
    // A bare YYYY-MM-DD is a calendar day: new Date() would read it as UTC
    // midnight, which is the day before anywhere west of UTC.
    let now;
    if (!referenceDate) {
        now = new Date();
    } else if (typeof referenceDate === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(referenceDate)) {
        now = parseLocalDate(referenceDate);
    } else {
        now = new Date(referenceDate);
    }

    switch (period) {
        case 'weekly': {
            // Monday to Sunday of current week
            const weekStart = new Date(now);
            const dayOfWeek = weekStart.getDay();
            const daysToMonday = dayOfWeek === 0 ? -6 : 1 - dayOfWeek;
            weekStart.setDate(weekStart.getDate() + daysToMonday);

            const weekEnd = new Date(weekStart);
            weekEnd.setDate(weekEnd.getDate() + 6);

            return {
                start: formatDateForAPI(weekStart),
                end: formatDateForAPI(weekEnd),
                label: t('budget', 'Week of {date}', { date: weekStart.toLocaleDateString(userLocale(), { month: 'short', day: 'numeric' }) })
            };
        }

        case 'monthly': {
            if (startDay <= 1) {
                // Default: 1st to last day of current month
                const monthStart = new Date(now.getFullYear(), now.getMonth(), 1);
                const monthEnd = new Date(now.getFullYear(), now.getMonth() + 1, 0);

                return {
                    start: formatDateForAPI(monthStart),
                    end: formatDateForAPI(monthEnd),
                    label: now.toLocaleDateString(userLocale(), { month: 'long', year: 'numeric' })
                };
            }

            // Custom start day: clamp to days in month
            const currentDay = now.getDate();
            const daysInCurrentMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0).getDate();
            const effectiveStartDay = Math.min(startDay, daysInCurrentMonth);

            let periodStart, periodEnd;

            if (currentDay >= effectiveStartDay) {
                // Period started this month
                periodStart = new Date(now.getFullYear(), now.getMonth(), effectiveStartDay);

                // End is day before start day next month
                const nextMonth = now.getMonth() + 1;
                const daysInNextMonth = new Date(now.getFullYear(), nextMonth + 1, 0).getDate();
                const nextStartDay = Math.min(startDay, daysInNextMonth);
                // The calendar day before, not 24 hours before: a clocks-
                // forward day is 23 hours long, and that lost a day
                periodEnd = new Date(now.getFullYear(), nextMonth, nextStartDay - 1);
            } else {
                // Period started last month
                const prevMonth = now.getMonth() - 1;
                const daysInPrevMonth = new Date(now.getFullYear(), prevMonth + 1, 0).getDate();
                const prevStartDay = Math.min(startDay, daysInPrevMonth);
                periodStart = new Date(now.getFullYear(), prevMonth, prevStartDay);

                // End is the calendar day before this month's start day
                periodEnd = new Date(now.getFullYear(), now.getMonth(), effectiveStartDay - 1);
            }

            const label = periodStart.toLocaleDateString(userLocale(), { month: 'short', day: 'numeric' })
                + ' \u2013 '
                + periodEnd.toLocaleDateString(userLocale(), { month: 'short', day: 'numeric' });

            return {
                start: formatDateForAPI(periodStart),
                end: formatDateForAPI(periodEnd),
                label
            };
        }

        case 'quarterly': {
            // First to last day of current quarter
            const quarter = Math.ceil((now.getMonth() + 1) / 3);
            const quarterStartMonth = (quarter - 1) * 3;
            const quarterStart = new Date(now.getFullYear(), quarterStartMonth, 1);
            const quarterEnd = new Date(now.getFullYear(), quarterStartMonth + 3, 0);

            return {
                start: formatDateForAPI(quarterStart),
                end: formatDateForAPI(quarterEnd),
                label: `Q${quarter} ${now.getFullYear()}`
            };
        }

        case 'yearly': {
            // Jan 1 to Dec 31 of current year
            const yearStart = new Date(now.getFullYear(), 0, 1);
            const yearEnd = new Date(now.getFullYear(), 11, 31);

            return {
                start: formatDateForAPI(yearStart),
                end: formatDateForAPI(yearEnd),
                label: `${now.getFullYear()}`
            };
        }

        default:
            // Default to monthly
            return getPeriodDateRange('monthly', startDay, referenceDate);
    }
}

/**
 * The budget month a monthly cycle belongs to.
 *
 * The Budget page shows month M as the cycle containing M's 15th (it asks
 * getPeriodDateRange for `${budgetMonth}-15`), and a cycle holds exactly one
 * 15th: one that starts on or before the 15th is named after the month it
 * starts in, a later one after the month it ends in. Anything loading a
 * month's budget snapshot for a cycle must name it the same way, or a cycle
 * starting on the 10th would be paired with the following month's budgets.
 *
 * @param {string} start - Cycle start (YYYY-MM-DD)
 * @param {string} end - Cycle end (YYYY-MM-DD)
 * @returns {string} YYYY-MM
 */
export function budgetMonthForCycle(start, end) {
    return parseInt(start.slice(8, 10), 10) <= 15 ? start.slice(0, 7) : end.slice(0, 7);
}

/**
 * The budget month running on a given day (today by default): the month the
 * Budget page lists the current monthly cycle under.
 *
 * @param {number} [startDay=1] - Day of month the budget cycle starts
 * @param {Date|string} [referenceDate=null] - Stands in for "today"
 * @returns {string} YYYY-MM
 */
export function currentBudgetMonth(startDay = 1, referenceDate = null) {
    const cycle = getPeriodDateRange('monthly', startDay, referenceDate);
    return budgetMonthForCycle(cycle.start, cycle.end);
}

/**
 * The day the months of the dashboard charts and the month-by-month reports
 * start on: the budget start day when the user chose budget months for them
 * in Settings, otherwise 1, calendar months (#457). As
 * BudgetCarryoverService::reportMonthStartDay on the server.
 *
 * @param {object} settings - The user's settings
 * @returns {number} 1-31
 */
export function reportMonthStartDay(settings) {
    if (settings?.report_month_grouping !== 'budget') return 1;
    const startDay = parseInt(settings?.budget_start_day || '1', 10);
    return Number.isFinite(startDay) ? Math.min(31, Math.max(1, startDay)) : 1;
}

/**
 * Show or hide a note saying a chart's or report's months are budget months.
 *
 * @param {HTMLElement|null} el - The note element
 * @param {number} monthStartDay - As reportMonthStartDay(); 1 hides the note
 */
export function showMonthGroupingNote(el, monthStartDay) {
    if (!el) return;
    const budgetMonths = monthStartDay > 1;
    el.textContent = budgetMonths
        ? t('budget', 'Months are budget periods starting on day {day}, as chosen in Settings.', { day: monthStartDay })
        : '';
    el.style.display = budgetMonths ? '' : 'none';
}

/**
 * The dates a budget month covers: the calendar month, or with a budget start
 * day the cycle holding the month's 15th.
 *
 * @param {string} month - YYYY-MM
 * @param {number} [startDay=1] - Day of month the budget cycle starts
 * @returns {object} {start, end, label}
 */
export function budgetMonthRange(month, startDay = 1) {
    return getPeriodDateRange('monthly', startDay, `${month}-15`);
}

/**
 * The dates a quarterly or yearly budget has run by the end of a budget
 * month: from the start of the first budget month of its calendar quarter
 * or year to the end of the month, so with a budget start day it is made of
 * whole budget months. The Budget page shows a quarterly or yearly row's
 * spending over these dates beside the month's. As BudgetPeriod::toDateRange
 * on the server.
 *
 * @param {string} period - weekly, monthly, quarterly or yearly
 * @param {string} month - YYYY-MM
 * @param {number} [startDay=1] - Day of month the budget cycle starts
 * @returns {object|null} {start, end}, or null for a weekly or monthly budget
 */
export function periodToDateRange(period, month, startDay = 1) {
    const monthNumber = parseInt(month.slice(5, 7), 10);
    let first;
    if (period === 'yearly') first = 1;
    else if (period === 'quarterly') first = Math.floor((monthNumber - 1) / 3) * 3 + 1;
    else return null;
    return {
        start: budgetMonthRange(`${month.slice(0, 4)}-${String(first).padStart(2, '0')}`, startDay).start,
        end: budgetMonthRange(month, startDay).end,
    };
}

/**
 * Move a YYYY-MM month by whole months.
 *
 * @param {string} month - YYYY-MM
 * @param {number} offset - Signed number of months
 * @returns {string} YYYY-MM
 */
export function shiftMonth(month, offset) {
    const [year, mon] = month.split('-').map(Number);
    const d = new Date(year, mon - 1 + offset, 1);
    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
}

/** The date-range values a dashboard tile's settings can hold. */
export const TILE_DATE_RANGES = ['7d', '30d', '90d', '6m', '1y', 'period'];

/**
 * Shift a date by whole months, clamping to the target month's length.
 *
 * setMonth() alone overflows: six months back from 31 March is 31 September,
 * which lands on 1 October and silently widens the window by a day.
 *
 * @param {Date} date - Mutated in place
 * @param {number} months - Signed month offset
 */
function shiftMonthsClamped(date, months) {
    const day = date.getDate();
    date.setDate(1);
    date.setMonth(date.getMonth() + months);
    const daysInTargetMonth = new Date(date.getFullYear(), date.getMonth() + 1, 0).getDate();
    date.setDate(Math.min(day, daysInTargetMonth));
}

/**
 * Resolve a dashboard tile's date-range setting into the window it charts.
 *
 * The rolling ranges are literal: "Last 30 days" is the last 30 days, not the
 * month to date (#333). 'period' follows the user's own budget cycle, so a tile
 * answering "how much have I spent this cycle" agrees with the budget surfaces
 * instead of cutting the cycle in half at the month boundary.
 *
 * @param {string} dateRange - One of TILE_DATE_RANGES
 * @param {object} [options]
 * @param {number} [options.budgetStartDay=1] - Day of month the budget cycle starts ('period' only)
 * @param {string} [options.fallback='6m'] - Range to use when dateRange is not recognised
 * @param {Date|string} [options.referenceDate=null] - Stands in for "today"
 * @returns {object} {start, end, label} — label is the date span for 'period', else null
 */
export function resolveTileDateRange(dateRange, options = {}) {
    const { budgetStartDay = 1, fallback = '6m', referenceDate = null } = options;
    const now = referenceDate ? new Date(referenceDate) : new Date();

    // A tile can hold a range it no longer offers (its schema changed, or the
    // setting predates this list), so an unrecognised value resolves to the
    // caller's default rather than to an empty window. The second check keeps
    // an unrecognised fallback from resolving to nothing in turn.
    let key = dateRange;
    if (!TILE_DATE_RANGES.includes(key)) {
        key = TILE_DATE_RANGES.includes(fallback) ? fallback : '6m';
    }

    if (key === 'period') {
        const period = getPeriodDateRange('monthly', budgetStartDay, now);
        return { start: period.start, end: period.end, label: period.label };
    }

    const start = new Date(now);
    switch (key) {
        case '7d': start.setDate(start.getDate() - 7); break;
        case '30d': start.setDate(start.getDate() - 30); break;
        case '90d': start.setDate(start.getDate() - 90); break;
        case '1y': shiftMonthsClamped(start, -12); break;
        case '6m':
        default: shiftMonthsClamped(start, -6); break;
    }

    return {
        start: formatDateForAPI(start),
        end: formatDateForAPI(now),
        label: null,
    };
}

/** Forward horizons, in days, a bills tile can look ahead. */
export const FORWARD_HORIZONS = [30, 60, 90];

/** Horizons, in months, the cash-flow forecast can project. */
export const FORECAST_MONTHS = [3, 6, 12];

/** How many years the year-over-year tile can compare. */
export const YEARS_TO_COMPARE = [2, 3, 5];

/**
 * Resolve a numeric tile setting against the choices that tile offers.
 *
 * A saved value can be a string (a select reports one), absent, or a choice the
 * tile no longer offers, so anything unrecognised resolves to the fallback
 * rather than reaching a fetch as NaN.
 *
 * @param {number|string|undefined} value - The saved setting
 * @param {number[]} allowed - The choices this tile offers
 * @param {number} fallback - Used when value is not one of them
 * @returns {number}
 */
export function resolveTileNumberSetting(value, allowed, fallback) {
    const n = parseInt(value, 10);
    return allowed.includes(n) ? n : fallback;
}

/**
 * The equal-length window immediately before the given one.
 *
 * A comparison tile needs "the same length of time, just before" so the two
 * figures are like for like whatever range the user picked.
 *
 * @param {string} startDate - YYYY-MM-DD, inclusive
 * @param {string} endDate - YYYY-MM-DD, inclusive
 * @returns {object} {start, end} as YYYY-MM-DD
 */
export function precedingWindow(startDate, endDate) {
    const start = new Date(startDate + 'T00:00:00');
    const end = new Date(endDate + 'T00:00:00');
    const lengthDays = Math.round((end - start) / 86400000) + 1;

    const prevEnd = new Date(start);
    prevEnd.setDate(prevEnd.getDate() - 1);
    const prevStart = new Date(prevEnd);
    prevStart.setDate(prevStart.getDate() - (lengthDays - 1));

    return { start: formatDateForAPI(prevStart), end: formatDateForAPI(prevEnd) };
}

/**
 * The part of the previous period that matches how far the current one has
 * got: on the 3rd day of this period, the first 3 days of the last one. A
 * period in progress compared with a whole one reads "down 100%" on its first
 * day. Once the current period is over, or the previous one is the shorter,
 * the whole previous period counts.
 *
 * @param {object} previous - {start, end} as YYYY-MM-DD, inclusive
 * @param {object} current - {start, end} as YYYY-MM-DD, inclusive
 * @param {string} today - YYYY-MM-DD
 * @returns {object} {start, end} as YYYY-MM-DD
 */
export function comparablePreviousRange(previous, current, today) {
    if (today < current.start || today >= current.end) {
        return { start: previous.start, end: previous.end };
    }
    const end = parseLocalDate(previous.start);
    end.setDate(end.getDate() + daysBetweenDates(current.start, today));
    const endDate = formatDateForAPI(end);
    return { start: previous.start, end: endDate < previous.end ? endDate : previous.end };
}

/**
 * Pro-rate a budget amount from one period to another.
 *
 * @param {number} amount - Budget amount in the source period
 * @param {string} fromPeriod - Source period: 'weekly', 'monthly', 'quarterly', 'yearly'
 * @param {string} toPeriod - Target period: 'weekly', 'monthly', 'quarterly', 'yearly'
 * @returns {number} Pro-rated budget amount
 */
export function prorateBudget(amount, fromPeriod, toPeriod) {
    if (fromPeriod === toPeriod) {
        return amount;
    }

    // Conversion ratios (all relative to yearly)
    const yearlyMultipliers = {
        'weekly': 52,
        'monthly': 12,
        'quarterly': 4,
        'yearly': 1
    };

    // Convert to yearly amount first
    const yearlyAmount = amount * yearlyMultipliers[fromPeriod];

    // Convert from yearly to target period (full precision preserved for storage)
    return yearlyAmount / yearlyMultipliers[toPeriod];
}
